const router = Router();
const featureKey = "servers.firewall.isp.v1";
const secretPattern = /password|passwd|pwd|secret|token|credential|username|login|api.?key|private.?key|vpn|pppoe|wifi|ruleset|config(uration)?|backup.?key|license/i;
const hash = (value: unknown) => crypto.createHash("sha256").update(JSON.stringify(value)).digest("hex");
