const unknownFields = (body: Record<string, unknown>, allowed: string[]) => Object.keys(body).filter((key) => !allowed.includes(key));
const idempotencyKey = (req: AuthRequest) => typeof req.headers["idempotency-key"] === "string" ? req.headers["idempotency-key"].trim() : "";
