router.use("/isp-circuits/:id/addresses", async (req: AuthRequest, res, next) => { if (req.method !== "POST") return next(); const body = req.body as Record<string, unknown>; const address = typeof body.address === "string" ? body.address : ""; const prefix = Number(body.prefixLength); const gateway = typeof body.gateway === "string" ? body.gateway : null; if (!isIP(address) || (gateway && !isIP(gateway)) || !Number.isInteger(prefix) || prefix < 0 || prefix > (isIP(address) === 4 ? 32 : 128)) return res.status(400).json({ error: "address, gateway, and prefixLength must be valid IP values.", code: "INVALID_IP_ADDRESS" }); next(); });
router.use("/isp-circuits/:id/equipment", async (req: AuthRequest, res, next) => { if (req.method !== "POST") return next(); const assetId = typeof req.body?.assetId === "string" ? req.body.assetId : ""; const [circuit, asset] = await Promise.all([prisma.ispCircuit.findUnique({ where: { id: req.params.id }, select: { branchId: true } }), prisma.asset.findUnique({ where: { id: assetId }, select: { branchId: true } })]); const approval = req.body?.sharedServiceApproved === true && typeof req.body?.sharedServiceReason === "string" && req.body.sharedServiceReason.trim(); if (circuit && asset && circuit.branchId !== asset.branchId && !approval) return res.status(400).json({ error: "Cross-branch equipment requires explicit shared-service approval and reason.", code: "SHARED_SERVICE_APPROVAL_REQUIRED" }); (req as AuthRequest & { sharedServiceApproval?: { approved: boolean; reason?: string } }).sharedServiceApproval = { approved: Boolean(approval), reason: approval ? String(req.body.sharedServiceReason).trim() : undefined }; delete req.body.sharedServiceApproved; delete req.body.sharedServiceReason; next(); });
