router.use("/isp-circuits/:id/addresses/:addressId/end", async (req: AuthRequest, res, next) => { if (req.method !== "POST") return next(); const expected = typeof req.body?.expectedUpdatedAt === "string" ? new Date(req.body.expectedUpdatedAt) : null; const item = await prisma.ispCircuitAddress.findUnique({ where: { id: req.params.addressId }, select: { updatedAt: true } }); if (item && (!expected || expected.getTime() !== item.updatedAt.getTime())) return res.status(409).json({ error: "Address changed since it was loaded.", code: "STALE_WRITE" }); next(); });
router.use("/isp-circuits/:id/equipment/:assignmentId/end", async (req: AuthRequest, res, next) => { if (req.method !== "POST") return next(); const expected = typeof req.body?.expectedUpdatedAt === "string" ? new Date(req.body.expectedUpdatedAt) : null; const item = await prisma.circuitEquipmentAssignment.findUnique({ where: { id: req.params.assignmentId }, select: { updatedAt: true } }); if (item && (!expected || expected.getTime() !== item.updatedAt.getTime())) return res.status(409).json({ error: "Equipment assignment changed since it was loaded.", code: "STALE_WRITE" }); next(); });
